372: function getVehicleStats() {
373:   const lowRangeMul = state.lowRange ? 1.5 : 1;
374:   const diffMul = state.diffLock
375:     ? 1 + (state.build.lockerRear ? 0.15 : 0) + (state.build.lockerFront ? 0.1 : 0)
376:     : 1;
377:   const tractionBonus = state.build.portalAxles ? 0.12 : 0;
378:   const clearance = 220 + (state.build.portalAxles ? 90 : 0) + (state.build.springOver ? 75 : 0);
379:   const fordDepth = 0.55 + (state.build.snorkel ? 0.2 : 0) + (state.build.portalAxles ? 0.12 : 0);
380:   const recoveryPower = 3.5 + (state.build.winch ? 1.2 : 0);
381:   return {
382:     lowRangeMul,
383:     diffMul,
384:     tractionBonus,
385:     clearance,
386:     fordDepth,
387:     recoveryPower,
388:     shockProtection: state.build.shafts ? 0.18 : 0,
389:     tireWearMultiplier: state.build.beadlocks && state.tirePressure <= 8 ? 0.85 : 1,
390:     maxSpeed: state.lowRange ? 52 : 100,
391:     steer: 1.4,
392:     acceleration: (state.lowRange ? 58 : 92) * (state.lowRange && state.build.transferCase ? 1.32 : 1),
393:     braking: 96,
394:     traction: 1 + tractionBonus,
395:     tirePressure: state.tirePressure,
396:     canBite: state.build.beadlocks || state.build.ctis
397:   };
398: }
