408: function updateMission() {
409:   const mission = document.getElementById('missionName');
410:   const desc = document.getElementById('missionDesc');
411:   const objectiveList = document.getElementById('objectiveList');
412:   const objectiveLabel = document.getElementById('objectiveLabel');
413:   const progressText = document.getElementById('progressText');
414:   const missionProgress = document.getElementById('missionProgress');
415:   const progress = state.objectiveCompleted.filter(Boolean).length;
416: 
417:   const labels = [
418:     'REACH THE OLD LOGGING ROAD',
419:     'TEST THE BOG LINE',
420:     'TOP OUT AT THE RIDGE BEACON'
421:   ];
422: 
423:   mission.textContent = missionStops[state.missionIndex].label === 'Ridge beacon' ? 'The Ridge Beacon' : 'The Old Logging Road';
424:   desc.textContent =
425:     state.missionIndex === 0
426:       ? 'Reach the ridge marker. Keep to the old logging road; the thaw has turned the low ground to soup.'
427:       : state.missionIndex === 1
428:         ? 'Cross the bog line without frying the clutch. Keep wheel spin under control and avoid dead stopping.'
429:         : 'Climb to the ridge, anchor, and get the scout team on the radio.';
430: 
431:   objectiveList.innerHTML = missionStops.map((stop, idx) => {
432:     const complete = state.objectiveCompleted[idx];
433:     const current = idx === state.missionIndex && !complete;
434:     return `
435:       <div class="objective ${complete ? 'done' : current ? 'current' : ''}">
436:         <span class="check">${complete ? '✓' : idx + 1}</span>
437:         <span>${stop.label}</span>
438:       </div>
439:     `;
440:   }).join('');
441: 
442:   objectiveLabel.textContent = labels[state.missionIndex] || 'CLEAR MISSION';
443:   progressText.textContent = `${progress} / ${missionStops.length}`;
444:   missionProgress.style.width = `${(progress / missionStops.length) * 100}%`;
445: 
446:   const missionState = document.getElementById('toast');
447:   if (progress >= 3) {
448:     missionState.textContent = 'MISSION COMPLETE';
449:     missionState.classList.add('show');
450:   }
451: }
