474: function drawWorld() {
475:   const viewX = player.x - canvas.clientWidth / 2;
476:   const viewY = player.y - canvas.clientHeight / 2;
477:   const visibleW = canvas.clientWidth;
478:   const visibleH = canvas.clientHeight;
479: 
480:   ctx.clearRect(0, 0, visibleW, visibleH);
481:   ctx.fillStyle = '#1c2a23';
482:   ctx.fillRect(0, 0, visibleW, visibleH);
483: 
484:   const startX = Math.floor((viewX - 40) / world.tile) * world.tile;
485:   const startY = Math.floor((viewY - 40) / world.tile) * world.tile;
486:   const endX = Math.ceil((viewX + visibleW + 40) / world.tile) * world.tile;
487:   const endY = Math.ceil((viewY + visibleH + 40) / world.tile) * world.tile;
488: 
489:   for (let y = startY; y < endY; y += world.tile) {
490:     for (let x = startX; x < endX; x += world.tile) {
491:       const terrain = sampleTerrain(x + world.tile * 0.5, y + world.tile * 0.5);
492:       const px = x - viewX;
493:       const py = y - viewY;
494:       ctx.fillStyle = terrain.color;
495:       ctx.fillRect(px, py, world.tile + 1, world.tile + 1);
496:     }
497:   }
498: 
499:   ctx.lineCap = 'round';
500:   ctx.lineJoin = 'round';
501:   ctx.strokeStyle = '#7f8d66';
502:   ctx.lineWidth = 22;
503:   ctx.beginPath();
504:   world.route.forEach((point, idx) => {
505:     const px = point.x - viewX;
506:     const py = point.y - viewY;
507:     if (idx === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
508:   });
509:   ctx.stroke();
510: 
511:   ctx.strokeStyle = '#d9d6c2';
512:   ctx.lineWidth = 4;
513:   ctx.beginPath();
514:   world.route.forEach((point, idx) => {
515:     const px = point.x - viewX;
516:     const py = point.y - viewY;
517:     if (idx === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
518:   });
519:   ctx.stroke();
520: 
521:   ctx.strokeStyle = '#4a7d90';
522:   ctx.lineWidth = 12;
523:   ctx.beginPath();
524:   world.river.forEach((point, idx) => {
525:     const px = point.x - viewX;
526:     const py = point.y - viewY;
527:     if (idx === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
528:   });
529:   ctx.stroke();
530: 
531:   missionStops.forEach((stop, idx) => {
532:     const px = stop.x - viewX;
533:     const py = stop.y - viewY;
534:     const active = idx === state.missionIndex && !state.objectiveCompleted[idx];
535:     ctx.beginPath();
536:     ctx.fillStyle = active ? '#d8db85' : '#d7d4be';
537:     ctx.arc(px, py, 10, 0, Math.PI * 2);
538:     ctx.fill();
539:     ctx.beginPath();
540:     ctx.strokeStyle = active ? '#c7cf5c' : '#7f8d79';
541:     ctx.lineWidth = 2;
542:     ctx.arc(px, py, stop.radius, 0, Math.PI * 2);
543:     ctx.stroke();
544:   });
545: 
546:   if (state.winchActive && state.winchAnchor) {
547:     const hook = getWinchHookPosition();
548:     ctx.beginPath();
549:     ctx.moveTo(hook.x - viewX, hook.y - viewY);
550:     ctx.lineTo(state.winchAnchor.x - viewX, state.winchAnchor.y - viewY);
551:     ctx.strokeStyle = '#d7d4be';
552:     ctx.lineWidth = 2;
553:     ctx.setLineDash([7, 5]);
554:     ctx.stroke();
555:     ctx.setLineDash([]);
556:     ctx.beginPath();
557:     ctx.arc(state.winchAnchor.x - viewX, state.winchAnchor.y - viewY, 6, 0, Math.PI * 2);
558:     ctx.fillStyle = '#c0dc68';
559:     ctx.fill();
560:   }
561: 
562:   const px = player.x - viewX;
563:   const py = player.y - viewY;
564:   ctx.save();
565:   ctx.translate(px, py);
566:   ctx.rotate(player.dir);
567:   ctx.fillStyle = '#7f8d63';
568:   ctx.fillRect(-24, -12, 48, 24);
569:   ctx.fillStyle = '#d9dcbf';
570:   ctx.fillRect(-15, -10, 30, 20);
571:   ctx.fillStyle = '#233127';
572:   ctx.fillRect(-32, -20, 20, 16);
573:   ctx.fillRect(12, -20, 20, 16);
574:   ctx.fillStyle = '#161a17';
575:   ctx.fillRect(-24, -16, 8, 8);
576:   ctx.fillRect(16, -16, 8, 8);
577:   ctx.fillRect(-24, 8, 8, 8);
578:   ctx.fillRect(16, 8, 8, 8);
579:   ctx.restore();
580: }
