820: function generateUpgradeGrid() {
821:   const grid = document.getElementById('upgradeGrid');
822:   const currentFilter = document.querySelector('.filter-btn.active')?.dataset.filter || 'all';
823: 
824:   grid.innerHTML = upgrades.map((item) => {
825:     const installed = state.build[item.id] || false;
826:     const price = state.money >= item.cost ? 'AVAILABLE' : 'LOW FUNDS';
827:     const type = item.type;
828:     const visible = currentFilter === 'all' || type === currentFilter;
829:     if (!visible) return '';
830: 
831:     return `
832:       <article class="upgrade-card ${installed ? 'installed' : state.money >= item.cost ? '' : 'locked'}" data-id="${item.id}">
833:         <span class="upgrade-type">${item.type.toUpperCase()}</span>
834:         <h3>${item.name}</h3>
835:         <p>${item.description}</p>
836:         <div class="upgrade-bottom">
837:           <span class="upgrade-cost">₽ ${formatCash(item.cost)}</span>
838:           <span class="upgrade-state ${installed ? '' : 'lock'}">${installed ? 'INSTALLED' : state.money >= item.cost ? 'BUY' : 'LOCKED'}</span>
839:         </div>
840:         <button class="upgrade-action" type="button" data-upgrade="${item.id}" aria-label="Upgrade ${item.name}"></button>
841:       </article>
842:     `;
843:   }).join('');
844: 
845:   grid.querySelectorAll('.upgrade-action').forEach((button) => {
846:     button.addEventListener('click', () => {
847:       const id = button.dataset.upgrade;
848:       const match = upgrades.find((item) => item.id === id);
849:       if (!match) return;
850:       if (state.build[id]) {
851:         showToast(`${match.name} already installed.`);
852:         return;
853:       }
854:       if (state.money < match.cost) {
855:         showToast('Not enough funds for this part.');
856:         return;
857:       }
858:       state.money -= match.cost;
859:       state.build[id] = true;
860:       generateUpgradeGrid();
861:       syncBuildSummary();
862:       showToast(`${match.name} installed.`);
863:     });
864:   });
