import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({channel:'chromium',headless:true,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:1280,height:1000},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3000',{waitUntil:'load'});await page.waitForFunction(()=>document.fonts.status==='loaded');
const state=[];
for(let i=0;i<3;i++) state.push(await page.evaluate(index=>{player.x=missionStops[index].x;player.y=missionStops[index].y;checkMission();return {objectives:[...state.objectiveCompleted],timeline:[...document.querySelectorAll('#timeline .timeline-item')].map(e=>e.classList.contains('active')?'active':e.classList.contains('completed')?'completed':'upcoming')}},i));
const thermal=await page.evaluate(()=>{player.engineTemp=130;player.clutchTemp=170;updateVehicleUI();return [document.querySelector('#engineTemp').className,document.querySelector('#clutchTemp').className]});
await page.screenshot({path:'/tmp/opencode/taiga-check/latest.jpg',type:'jpeg',quality:85,fullPage:true});
console.log(JSON.stringify({progression:state,thermal,errors},null,2));await browser.close();
